// Edite estes valores antes de cada execução da campanha.
return [{
  json: {
    campanha_id: 1,
    curva: 'padrao',            // 'padrao' (8.1, cenário B) ou 'acelerada' (8.2, cenários A/D)
    data_inicio: '2026-08-17',  // primeiro dia útil de disparo, formato YYYY-MM-DD
    wa_tier_limite: 1000,       // limite diário do tier no WhatsApp Manager (seção 1.2)
  },
}];

const params = $('Parâmetros').first().json;

const counts = {};
for (const it of items) {
  counts[it.json.canal] = parseInt(it.json.contagem, 10) || 0;
}
const totalEmail = counts.email || 0;

const CURVA_PADRAO = [200, 500, 1200, 2000, 2500, 2500];
const CURVA_ACELERADA = [500, 1500, 3000, 3000];
const curva = params.curva === 'acelerada' ? CURVA_ACELERADA : CURVA_PADRAO;

function proximoDiaUtil(d) {
  while (d.getUTCDay() === 0 || d.getUTCDay() === 6) {
    d = new Date(d.getTime() + 86400000);
  }
  return d;
}

function gerarDias(qtd) {
  const dias = [];
  let d = proximoDiaUtil(new Date(params.data_inicio + 'T00:00:00Z'));
  for (let i = 0; i < qtd; i++) {
    dias.push(d.toISOString().slice(0, 10));
    d = proximoDiaUtil(new Date(d.getTime() + 86400000));
  }
  return dias;
}

const dias = gerarDias(curva.length + 1); // +1 = dia final com o "restante"
const acumuladoCurva = curva.reduce((a, b) => a + b, 0);
const restante = Math.max(totalEmail - acumuladoCurva, 0);
const limitesEmail = [...curva, restante];

const waLimiteDiario = Math.max(Math.floor((params.wa_tier_limite || 0) * 0.9), 0);

const linhas = [];
dias.forEach((dia, i) => {
  linhas.push({ campanha_id: params.campanha_id, canal: 'email', dia, limite: limitesEmail[i] });
  linhas.push({ campanha_id: params.campanha_id, canal: 'whatsapp', dia, limite: waLimiteDiario });
});

return [{ json: { linhas, totalEmail } }];

