INSERT INTO cota_diaria (campanha_id, canal, dia, limite)
SELECT * FROM jsonb_to_recordset($1::jsonb) AS t(campanha_id int, canal text, dia date, limite int)
ON CONFLICT (campanha_id, canal, dia) DO UPDATE SET limite = EXCLUDED.limite;
